/* config.h for the Emscripten (browser) build of xgalaga-hyperspace.
 * Normally generated by ./configure; hand-written here because the browser
 * build compiles the sources directly with emcc.
 */
#ifndef WEB_CONFIG_H
#define WEB_CONFIG_H

#define STDC_HEADERS 1
#define HAVE_UNISTD_H 1
#define HAVE_SYS_TIME_H 1
#define HAVE_FCNTL_H 1
#define HAVE_STRINGS_H 1
#define HAVE_RANDOM 1
#define HAVE_LRAND48 1
#define HAVE_GETTIMEOFDAY 1

/* Web Audio sound support (see web/sound_web.c) */
#define SOUND 1
/* NAS sound server is not available in the browser */
/* #undef NAS_SOUND */

/* Path strings (sound/level files are embedded; these are informational) */
#define SOUNDDIR "/sounds"
#define SOUNDDEV "/dev/null"
#define SOUNDSERVER ""
#define SOUNDSRVDIR "/"
#define LEVELDIR "/levels"
#define IMAGEDIR "/images"
#define SCOREFILE "/tmp/xgal_global_scores"
#define CREDITSFILE "/tmp/xgal_credits"
#define XGALAGADIR "/usr/local/"

#endif /* WEB_CONFIG_H */
